from datetime import date


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self._books = set()          # all known book ids
        self._borrowed = {}          # book_id -> (user, due_date)
        self._fines = {}             # user -> outstanding fine

    def add_book(self, book_id: str) -> None:
        if book_id in self._books:
            raise ValueError(f"Book {book_id!r} already in library")
        self._books.add(book_id)

    def _user_holds(self, user: str):
        return [bid for bid, (u, _) in self._borrowed.items() if u == user]

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books:
            raise ValueError(f"Unknown book {book_id!r}")
        if book_id in self._borrowed:
            raise ValueError(f"Book {book_id!r} is already borrowed")
        if self._user_holds(user):
            raise ValueError(f"User {user!r} already holds a book")

        due = date.fromordinal(day.toordinal() + self.loan_days)
        self._borrowed[book_id] = (user, due)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self._borrowed:
            raise ValueError(f"Book {book_id!r} is not borrowed")
        holder, due = self._borrowed[book_id]
        if holder != user:
            raise ValueError(
                f"User {user!r} has not borrowed book {book_id!r}"
            )

        del self._borrowed[book_id]

        delay = (day - due).days
        fine = self.daily_fine * delay if delay > 0 else 0.0
        if fine:
            self._fines[user] = self._fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self._fines.pop(user, None)
